// Opt-in low-resolution contact sheet frames; originals never leave the browser.
export async function visualContext(assets,attached=[]){const pool=assets.filter(a=>!a.builtin&&a.type!=='audio'&&(!attached.length||attached.includes(a.id))).slice(0,4),frames=[];for(const a of pool){let source,cleanup=()=>{};try{if(a.type==='image'){source=new Image();source.src=a.src;await source.decode()}else{source=document.createElement('video');source.muted=true;source.playsInline=true;source.preload='auto';cleanup=()=>{source.pause();source.removeAttribute('src');source.load()};source.src=a.src;await ready(source,'loadeddata',()=>source.readyState>=2)}const times=a.type==='image'?[0]:[Math.min(.2,a.duration*.1),a.duration*.65];for(const t of times){if(a.type==='video'&&Math.abs(source.currentTime-t)>.01){source.currentTime=t;await ready(source,'seeked',()=>!source.seeking&&source.readyState>=2)}const iw=source.videoWidth||source.naturalWidth,ih=source.videoHeight||source.naturalHeight,scale=Math.min(1,320/Math.max(iw,ih)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(iw*scale));canvas.height=Math.max(1,Math.round(ih*scale));canvas.getContext('2d').drawImage(source,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.5);if(data.length>16000)data=canvas.toDataURL('image/jpeg',.2);if(data.length>16000)throw Error('Кадр слишком сложный. Отключите анализ кадров или выберите другой исходник.');frames.push({assetId:a.id,time:Math.round(t*100)/100,data})}}finally{cleanup()}}return frames}
function ready(video,event,done){if(done())return Promise.resolve();return new Promise((resolve,reject)=>{const finish=error=>{clearTimeout(timer);video.removeEventListener(event,ok);video.removeEventListener('error',bad);error?reject(error):resolve()},ok=()=>finish(),bad=()=>finish(Error('Не удалось получить кадры из видео.')),timer=setTimeout(()=>finish(Error('Истекло ожидание кадра.')),12000);video.addEventListener(event,ok,{once:true});video.addEventListener('error',bad,{once:true})})}
